class Solution {
    public int maxArea(int[] height) {
        int left = 0, right = height.length - 1;
        int maxArea = 0;

        while (left < right) {
            // Calculate area with current pointers
            int width = right - left;
            int h = Math.min(height[left], height[right]);
            int area = width * h;
            maxArea = Math.max(maxArea, area);

            // Move the pointer with smaller height
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }

        return maxArea;
    }
}

class Solution {
    public int maxArea(int[] height) {
        int left = 0, right = height.length - 1;
        int maxArea = 0;

        while (left < right) {
            int h = Math.min(height[left], height[right]);
            maxArea = Math.max(maxArea, h * (right - left));

            // Skip all heights <= current minimum on left side
            if (height[left] < height[right]) {
                int currentLeft = height[left];
                while (left < right && height[left] <= currentLeft) {
                    left++;
                }
            } else {
                // Skip all heights <= current minimum on right side
                int currentRight = height[right];
                while (left < right && height[right] <= currentRight) {
                    right--;
                }
            }
        }

        return maxArea;
    }
}

class Solution {
    public int maxArea(int[] height) {
        int maxArea = 0;
        int n = height.length;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int h = Math.min(height[i], height[j]);
                int width = j - i;
                maxArea = Math.max(maxArea, h * width);
            }
        }

        return maxArea;
    }
}
